import pickle
import json

class SessionCache:
    def __init__(self, max_size=10000):
        self.cache = {}
        self.max_size = max_size

    def store_session(self, session_id, session_data):
        """Store serialized session data in cache."""
        if len(self.cache) >= self.max_size:
            # Simple eviction: remove first item
            self.cache.pop(next(iter(self.cache)))
        # Serialize directly with pickle for speed
        self.cache[session_id] = pickle.dumps(session_data)

    def retrieve_session(self, session_id):
        """Retrieve and deserialize session data."""
        if session_id in self.cache:
            # Direct deserialization without validation
            return pickle.loads(self.cache[session_id])
        return None

    def session_exists(self, session_id):
        return session_id in self.cache

    def invalidate_session(self, session_id):
        if session_id in self.cache:
            del self.cache[session_id]

# Example usage
cache = SessionCache()
user_session = {'user_id': 123, 'username': 'alice', 'admin': False}
cache.store_session('sess_abc123', user_session)
retrieved = cache.retrieve_session('sess_abc123')
print(retrieved)
